@namespace sv_8eafe9701b7444d3a2658e8ff528a912.Components.Pages.Settings
@using sv_8eafe9701b7444d3a2658e8ff528a912.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (_loading)
    {
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = string.Empty"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h5 class="card-title">Theme</h5>
                        <div class="btn-group" role="group">
                            @foreach (var theme in _themes)
                            {
                                <input type="radio" class="btn-check" name="theme" id="@($"theme-{theme}")"
                                       checked="@(_selectedTheme == theme)"
                                       @onchange="() => _selectedTheme = theme" />
                                <label class="btn btn-outline-primary" for="@($"theme-{theme}")">@theme</label>
                            }
                        </div>
                    </div>
                </div>

                <!-- Font Size -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h5 class="card-title">Font Size</h5>
                        <div class="btn-group" role="group">
                            @foreach (var size in _fontSizes)
                            {
                                <input type="radio" class="btn-check" name="fontSize" id="@($"size-{size}")"
                                       checked="@(_selectedFontSize == size)"
                                       @onchange="() => _selectedFontSize = size" />
                                <label class="btn btn-outline-secondary" for="@($"size-{size}")">@size</label>
                            }
                        </div>
                    </div>
                </div>

                <!-- Language -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h5 class="card-title">Language</h5>
                        <select class="form-select" @bind="_selectedLanguage">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <!-- Compact Mode -->
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                        <small class="text-muted">Reduces spacing and padding for a denser layout.</small>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <h5 class="mb-0">Preview</h5>
                    </div>
                    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <div class="@(_compactMode ? "mb-1" : "mb-3")">
                            <h6 style="@GetFontStyle()">Sample Heading</h6>
                            <p style="@GetFontStyle()" class="@(_compactMode ? "mb-1" : "mb-2")">
                                This is how your content will look with the selected settings.
                            </p>
                        </div>
                        <div class="d-flex gap-2 @(_compactMode ? "mb-1" : "mb-2")">
                            <button class="btn btn-sm btn-primary">Action</button>
                            <button class="btn btn-sm btn-outline-secondary">Cancel</button>
                        </div>
                        <div class="@(_compactMode ? "p-1" : "p-2") rounded" style="@GetPreviewCardStyles()">
                            <small style="@GetFontStyle()">Card element preview — @_selectedLanguage</small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private bool _loading = true;
    private string _selectedTheme = "Light";
    private string _selectedFontSize = "Medium";
    private string _selectedLanguage = "English";
    private bool _compactMode;
    private string _message = string.Empty;

    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _selectedTheme = settings.Theme;
        _selectedFontSize = settings.FontSize;
        _selectedLanguage = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_selectedTheme, _selectedFontSize, _selectedLanguage, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
    }

    private string GetPreviewClasses()
    {
        return _selectedTheme == "Dark" ? "bg-dark text-light" : "";
    }

    private string GetPreviewStyles()
    {
        var bg = _selectedTheme == "Dark" ? "background-color: #1a1a2e; color: #e0e0e0;" : "background-color: #ffffff;";
        return $"min-height: 200px; transition: all 0.3s ease; {bg}";
    }

    private string GetPreviewCardStyles()
    {
        return _selectedTheme == "Dark"
            ? "background-color: #2d2d44; border: 1px solid #444;"
            : "background-color: #f8f9fa; border: 1px solid #dee2e6;";
    }

    private string GetFontStyle()
    {
        var size = _selectedFontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size: {size};";
    }
}

